extern "C" unsigned strlen(const char *);

struct string_buf {
    int refs;
    int capacity;
    int char_length;
};

class stringx {
public:
    char *chars;
    string_buf *my_buf;

    stringx();
    stringx(const stringx &);
    ~stringx();
    void make_room(int);
    void append(const char *, int = -1);
    void append(const stringx &);
};

inline stringx operator+(const stringx &lhs, const char *rhs)
{
    stringx result;
    int len = strlen(rhs);
    result.make_room(len + lhs.my_buf->char_length);
    result.append(lhs);
    result.append(rhs, len);
    return result;
}

inline stringx operator+(const stringx &lhs, const stringx &rhs)
{
    stringx result;
    result.make_room(lhs.my_buf->char_length + rhs.my_buf->char_length);
    result.append(lhs);
    result.append(rhs);
    return result;
}

struct script_instance {
    void *owner;
    stringx name;
    const stringx &get_name() const { return name; }
};

struct vm_executable {
    char padding[12];
    stringx fullname;
    const stringx &get_fullname() const { return fullname; }
};

struct vm_thread {
    script_instance *inst;
    const vm_executable *ex;
    script_instance *get_instance() const { return inst; }
    const vm_executable *get_executable() const { return ex; }
};

class vm_stack {
public:
    int salloc;
    char *buffer;
    char *SP;
    vm_thread *my_thread;

    vm_thread *get_thread() const { return my_thread; }
    bool push(const char *, int);
};

struct vector3d {
    float x, y, z;
};

class script_library_class {
public:
    class function {
    public:
        enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
        virtual ~function();
        virtual bool operator()(vm_stack &, entry_t) { return true; }
    };
};

extern vector3d script_bsp_hit_norm;
__asm__(".equ script_bsp_hit_norm, 0x0057A8E0");

extern void error(const stringx &);

class slf_get_bsp_check_hit_norm_t : public script_library_class::function {
public:
    virtual bool operator()(vm_stack& stack, entry_t entry)
    {
        vector3d result = script_bsp_hit_norm;
        if (!stack.push((char*)&result,sizeof(result)) )
            error( stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname() );
        return true;
    }
};

